window.__until=async(fn,ms=20000)=>{const end=Date.now()+ms;while(Date.now()<end){try{if(await fn())return true;}catch{}await new Promise(resolve=>setTimeout(resolve,40));}return false;};
window.__slBaseApi=api;window.__slReadGate=null;window.__slValidationGate=null;window.__slCalls=[];window.__slChanges=[];window.__slKeys=[];window.__slClicks=[];window.__slErrors=[];
addEventListener('error',event=>__slErrors.push(event.message));addEventListener('unhandledrejection',event=>__slErrors.push(String(event.reason)));
els.setupsList.addEventListener('change',event=>__slChanges.push({trusted:event.isTrusted,value:els.setupsList.value,pending:setupsPending,ready:setupsReady,ticket:setupsTicket}),{capture:true});
els.setupsList.addEventListener('click',event=>__slClicks.push({trusted:event.isTrusted,target:event.target.tagName,value:els.setupsList.value}),{capture:true});
els.setupsList.addEventListener('keydown',event=>__slKeys.push({trusted:event.isTrusted,key:event.key,value:els.setupsList.value}),{capture:true});
window.__slReadCount=()=>__slCalls.filter(call=>call.path==='/api/presets'&&call.method==='GET').length;
window.__slFrames=()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
api=async(path,options)=>{const method=options?.method||'GET';__slCalls.push({path,method});const read=__slReadGate;if(path==='/api/presets'&&method==='GET'&&read&&!read.captured){read.captured=true;read.snapshot=await __slBaseApi(path,options);read.ticket=setupsTicket;await new Promise(resolve=>{read.release=resolve;});read.returned=true;return read.snapshot;}const validation=__slValidationGate;if(path===validation?.path&&method==='POST'&&!validation.captured){validation.captured=true;validation.snapshot=await __slBaseApi(path,options);validation.ticket=setupsTicket;await new Promise(resolve=>{validation.release=resolve;});validation.returned=true;return validation.snapshot;}return __slBaseApi(path,options);};
window.__slCreate=async(name,prompt)=>__slBaseApi('/api/presets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,model_id:loadedModel,payload:{...captureSetup(),prompt},model_revision:modelRevision,step_cache:null})});
window.__slUpdate=async(item,name)=>__slBaseApi('/api/presets/'+item.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,model_id:loadedModel,payload:item.payload,revision:item.revision,model_revision:modelRevision,step_cache:null})});
